import{_ as d,C as l,o,c as u,a2 as t,b as i,w as a,a as n,E as s,a3 as c}from"./chunks/framework.CgxQ0r6v.js";const A=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_2.md"}'),p={name:"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_2.md"};function m(g,e,h,b,v,f){const r=l("Mermaid");return o(),u("div",null,[e[2]||(e[2]=t('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-edumatica" tabindex="-1">Materia: EduMática <a class="header-anchor" href="#materia-edumatica" aria-label="Permalink to &quot;Materia: EduMática&quot;">​</a></h2><h3 id="eje-tematico-la-microclase" tabindex="-1">Eje Temático: La Microclase <a class="header-anchor" href="#eje-tematico-la-microclase" aria-label="Permalink to &quot;Eje Temático: La Microclase&quot;">​</a></h3><hr><h2 id="🧭-introduccion-el-laboratorio-del-docente" tabindex="-1">🧭 Introducción: El Laboratorio del Docente <a class="header-anchor" href="#🧭-introduccion-el-laboratorio-del-docente" aria-label="Permalink to &quot;🧭 Introducción: El Laboratorio del Docente&quot;">​</a></h2><p>Imagina que eres un piloto de avión. Antes de volar un Boeing 747 con 300 pasajeros, pasas cientos de horas en un <strong>simulador de vuelo</strong>: un espacio controlado donde puedes practicar despegues, aterrizajes de emergencia y maniobras complejas sin poner en riesgo a nadie. Si cometes un error, lo analizas, lo corriges y lo intentas de nuevo.</p><p>La <strong>microclase</strong> es exactamente eso: un simulador de vuelo para docentes. Es un espacio académico seguro y controlado donde el futuro profesional de la educación (o en nuestro caso, de la informática educativa) practica la ejecución de una clase real, pero en miniatura: con tiempo reducido, ante un grupo pequeño de compañeros que actúan como evaluadores y alumnos al mismo tiempo.</p><p>No se trata de &quot;dar una clase corta&quot;. Se trata de <strong>demostrar dominio</strong> de las técnicas pedagógicas fundamentales en un entorno que permite la retroalimentación inmediata y la mejora continua.</p><hr><h2 id="🏛️-capitulo-i-fundamentos-de-la-microclase" tabindex="-1">🏛️ CAPÍTULO I: Fundamentos de la Microclase <a class="header-anchor" href="#🏛️-capitulo-i-fundamentos-de-la-microclase" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: Fundamentos de la Microclase&quot;">​</a></h2><h3 id="_1-1-definicion-formal" tabindex="-1">1.1 Definición Formal <a class="header-anchor" href="#_1-1-definicion-formal" aria-label="Permalink to &quot;1.1 Definición Formal&quot;">​</a></h3><p>Una microclase (o micro-enseñanza) es una <strong>técnica de formación docente</strong> que consiste en la planificación y ejecución de una sesión instruccional de duración reducida (generalmente entre 5 y 20 minutos), dirigida a un grupo pequeño de participantes, con el objetivo de practicar, observar y perfeccionar habilidades específicas de enseñanza.</p><h3 id="_1-2-caracteristicas-esenciales" tabindex="-1">1.2 Características Esenciales <a class="header-anchor" href="#_1-2-caracteristicas-esenciales" aria-label="Permalink to &quot;1.2 Características Esenciales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Característica</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Duración reducida</strong></td><td>Entre 5 y 20 minutos (dependiendo del objetivo).</td></tr><tr><td><strong>Grupo pequeño</strong></td><td>Generalmente entre 5 y 15 personas (los compañeros de clase).</td></tr><tr><td><strong>Tema delimitado</strong></td><td>Se aborda un solo concepto, habilidad o segmento de contenido.</td></tr><tr><td><strong>Estructura planificada</strong></td><td>Debe seguir una estructura pedagógica clara (Inicio, Desarrollo, Cierre).</td></tr><tr><td><strong>Retroalimentación</strong></td><td>Al finalizar, los observadores y el profesor evalúan la ejecución.</td></tr><tr><td><strong>Repetición</strong></td><td>Si es necesario, puede repetirse incorporando las correcciones.</td></tr></tbody></table><h3 id="_1-3-propositos-de-la-microclase" tabindex="-1">1.3 Propósitos de la Microclase <a class="header-anchor" href="#_1-3-propositos-de-la-microclase" aria-label="Permalink to &quot;1.3 Propósitos de la Microclase&quot;">​</a></h3>',15)),(o(),i(c,null,{default:a(()=>[s(r,{id:"mermaid-100",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20MC%5B%22%F0%9F%8E%AF%20Microclase%22%5D%20--%3E%20P1%5B%22Practicar%20t%C3%A9cnicas%20de%20ense%C3%B1anza%22%5D%0A%20%20%20%20MC%20--%3E%20P2%5B%22Desarrollar%20habilidades%20de%20comunicaci%C3%B3n%22%5D%0A%20%20%20%20MC%20--%3E%20P3%5B%22Experimentar%20con%20recursos%20did%C3%A1cticos%22%5D%0A%20%20%20%20MC%20--%3E%20P4%5B%22Recibir%20retroalimentaci%C3%B3n%20constructiva%22%5D%0A%20%20%20%20MC%20--%3E%20P5%5B%22Ganar%20confianza%20ante%20un%20grupo%22%5D%0A%0A%20%20%20%20style%20MC%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A%20%20%20%20style%20P1%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20P2%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20P3%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20P4%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20P5%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<hr><h2 id="🧩-capitulo-ii-los-elementos-de-una-microclase" tabindex="-1">🧩 CAPÍTULO II: Los Elementos de una Microclase <a class="header-anchor" href="#🧩-capitulo-ii-los-elementos-de-una-microclase" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Los Elementos de una Microclase&quot;">​</a></h2><p>Una microclase efectiva se compone de tres fases fundamentales, cada una con un propósito pedagógico específico. Estas fases se alinean directamente con los <strong>9 Eventos de Instrucción de Gagné</strong> que estudiamos en la Evaluación 1.</p><h3 id="_2-1-fase-de-inicio-3-5-minutos" tabindex="-1">2.1 Fase de Inicio (3-5 minutos) <a class="header-anchor" href="#_2-1-fase-de-inicio-3-5-minutos" aria-label="Permalink to &quot;2.1 Fase de Inicio (3-5 minutos)&quot;">​</a></h3><p>El inicio es el momento más crítico. Si no capturas la atención del grupo en los primeros 60 segundos, el resto de la clase será una lucha cuesta arriba.</p><p><strong>Objetivos del inicio:</strong></p><ul><li>Captar la atención del grupo.</li><li>Activar los conocimientos previos.</li><li>Presentar claramente el objetivo de la sesión.</li></ul><p><strong>Técnicas recomendadas:</strong></p><table tabindex="0"><thead><tr><th>Técnica</th><th>Descripción</th><th>Ejemplo</th></tr></thead><tbody><tr><td><strong>Pregunta provocadora</strong></td><td>Plantear una interrogante que genere curiosidad o conflicto cognitivo.</td><td>&quot;¿Sabían que el 90% de los problemas de una red se resuelven verificando un solo cable?&quot;</td></tr><tr><td><strong>Dato sorprendente</strong></td><td>Un hecho estadístico o curioso que impacte al grupo.</td><td>&quot;El primer virus informático fue creado en 1986 y se llamaba &#39;Brain&#39;.&quot;</td></tr><tr><td><strong>Demostración rápida</strong></td><td>Mostrar un resultado final antes de explicar el proceso.</td><td>Mostrar una página web funcionando antes de enseñar el código HTML.</td></tr><tr><td><strong>Anécdota o caso real</strong></td><td>Contar una historia breve que conecte emocionalmente.</td><td>&quot;Un cliente perdió toda su base de datos porque no tenía backup...&quot;</td></tr><tr><td><strong>Video corto</strong></td><td>Un clip de 30-60 segundos que introduzca el tema visualmente.</td><td>Un fragmento de un documental sobre inteligencia artificial.</td></tr></tbody></table><p><strong>Eventos de Gagné que se aplican en el Inicio:</strong></p><ol><li>✅ Ganar la atención (Evento 1).</li><li>✅ Informar los objetivos (Evento 2).</li><li>✅ Estimular conocimientos previos (Evento 3).</li></ol><h3 id="_2-2-fase-de-desarrollo-5-12-minutos" tabindex="-1">2.2 Fase de Desarrollo (5-12 minutos) <a class="header-anchor" href="#_2-2-fase-de-desarrollo-5-12-minutos" aria-label="Permalink to &quot;2.2 Fase de Desarrollo (5-12 minutos)&quot;">​</a></h3><p>Es el cuerpo principal de la microclase. Aquí se presenta el contenido nuevo, se guía al alumno y se provoca la participación activa.</p><p><strong>Objetivos del desarrollo:</strong></p><ul><li>Presentar el contenido de forma clara, secuencial y con apoyo visual.</li><li>Proporcionar ejemplos concretos y analogías.</li><li>Provocar la participación del grupo (preguntas, ejercicios, discusión).</li></ul><p><strong>Principios pedagógicos clave:</strong></p><table tabindex="0"><thead><tr><th>Principio</th><th>Descripción</th><th>Error común</th></tr></thead><tbody><tr><td><strong>De lo simple a lo complejo</strong></td><td>Siempre iniciar por los conceptos básicos antes de avanzar a los avanzados.</td><td>Empezar explicando excepciones antes de la regla general.</td></tr><tr><td><strong>De lo conocido a lo desconocido</strong></td><td>Conectar el contenido nuevo con algo que el alumno ya domina.</td><td>Usar jerga técnica sin definirla primero.</td></tr><tr><td><strong>De lo concreto a lo abstracto</strong></td><td>Mostrar ejemplos tangibles antes de las definiciones teóricas.</td><td>Dar la definición formal antes que el ejemplo práctico.</td></tr><tr><td><strong>Participación activa</strong></td><td>Incluir al menos una actividad donde el alumno haga algo (no solo escuche).</td><td>Monólogo de 15 minutos sin interacción.</td></tr></tbody></table><p><strong>Eventos de Gagné que se aplican en el Desarrollo:</strong> 4. ✅ Presentar el contenido (Evento 4). 5. ✅ Proporcionar guía de aprendizaje (Evento 5). 6. ✅ Provocar el desempeño (Evento 6). 7. ✅ Proporcionar retroalimentación (Evento 7).</p><h3 id="_2-3-fase-de-cierre-2-3-minutos" tabindex="-1">2.3 Fase de Cierre (2-3 minutos) <a class="header-anchor" href="#_2-3-fase-de-cierre-2-3-minutos" aria-label="Permalink to &quot;2.3 Fase de Cierre (2-3 minutos)&quot;">​</a></h3><p>El cierre no es simplemente decir &quot;eso es todo&quot;. Es un momento pedagógico fundamental para consolidar el aprendizaje, verificar la comprensión y preparar al alumno para la siguiente sesión.</p><p><strong>Objetivos del cierre:</strong></p><ul><li>Sintetizar los puntos clave de la sesión.</li><li>Verificar la comprensión (evaluación informal).</li><li>Conectar lo aprendido con aplicaciones futuras o temas posteriores.</li></ul><p><strong>Técnicas recomendadas:</strong></p><table tabindex="0"><thead><tr><th>Técnica</th><th>Descripción</th></tr></thead><tbody><tr><td><strong>Resumen participativo</strong></td><td>Pedir a los alumnos que mencionen los 3 puntos más importantes de la clase.</td></tr><tr><td><strong>Pregunta de verificación</strong></td><td>&quot;Si tuvieran que explicarle este tema a un amigo en 30 segundos, ¿qué le dirían?&quot;</td></tr><tr><td><strong>Conexión con la próxima clase</strong></td><td>&quot;Hoy vimos los fundamentos. La próxima clase aplicaremos esto en un laboratorio.&quot;</td></tr><tr><td><strong>Reto o tarea</strong></td><td>Dejar una actividad breve que refuerce lo aprendido.</td></tr></tbody></table><p><strong>Eventos de Gagné que se aplican en el Cierre:</strong> 8. ✅ Evaluar el desempeño (Evento 8). 9. ✅ Mejorar retención y transferencia (Evento 9).</p><hr><h2 id="🛡️-capitulo-iii-tecnicas-de-presentacion-y-oratoria" tabindex="-1">🛡️ CAPÍTULO III: Técnicas de Presentación y Oratoria <a class="header-anchor" href="#🛡️-capitulo-iii-tecnicas-de-presentacion-y-oratoria" aria-label="Permalink to &quot;🛡️ CAPÍTULO III: Técnicas de Presentación y Oratoria&quot;">​</a></h2><p>La calidad del contenido no compensa una mala ejecución. Estas son las habilidades fundamentales que se observan y evalúan durante una microclase:</p><h3 id="_3-1-comunicacion-verbal" tabindex="-1">3.1 Comunicación Verbal <a class="header-anchor" href="#_3-1-comunicacion-verbal" aria-label="Permalink to &quot;3.1 Comunicación Verbal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Habilidad</th><th>Descripción</th><th>Consejo</th></tr></thead><tbody><tr><td><strong>Volumen</strong></td><td>La voz debe ser audible para todos, sin gritar.</td><td>Proyecta desde el diafragma. Habla al fondo del salón, no a la primera fila.</td></tr><tr><td><strong>Ritmo</strong></td><td>Ni demasiado rápido (causa confusión) ni demasiado lento (causa aburrimiento).</td><td>Usa pausas estratégicas después de puntos clave para que el grupo procese.</td></tr><tr><td><strong>Claridad</strong></td><td>Articular bien las palabras. Evitar muletillas (&quot;este...&quot;, &quot;o sea...&quot;, &quot;verdad?&quot;).</td><td>Graba tu práctica y escúchala. Las muletillas se eliminan con conciencia.</td></tr><tr><td><strong>Vocabulario</strong></td><td>Adaptar el lenguaje al nivel del grupo. Definir todo término técnico antes de usarlo.</td><td>Usa analogías del mundo real para explicar conceptos abstractos.</td></tr></tbody></table><h3 id="_3-2-comunicacion-no-verbal" tabindex="-1">3.2 Comunicación No Verbal <a class="header-anchor" href="#_3-2-comunicacion-no-verbal" aria-label="Permalink to &quot;3.2 Comunicación No Verbal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Habilidad</th><th>Descripción</th><th>Consejo</th></tr></thead><tbody><tr><td><strong>Contacto visual</strong></td><td>Mirar a todo el grupo, no solo a una persona ni al piso/techo.</td><td>Divide mentalmente el salón en 3 zonas y alterna tu mirada entre ellas.</td></tr><tr><td><strong>Postura corporal</strong></td><td>Erguido, seguro, sin cruzar los brazos. Transmitir confianza.</td><td>Evita apoyarte en la mesa o darle la espalda al grupo por más de 5 segundos.</td></tr><tr><td><strong>Desplazamiento</strong></td><td>Moverse con intención por el espacio. No quedarse clavado en un solo punto.</td><td>Camina hacia el grupo cuando hagas una pregunta; retrocede cuando expliques.</td></tr><tr><td><strong>Gesticulación</strong></td><td>Usar las manos para enfatizar puntos clave.</td><td>Evita jugar con objetos (marcadores, llaves) o meter las manos en los bolsillos.</td></tr></tbody></table><h3 id="_3-3-manejo-de-recursos-didacticos" tabindex="-1">3.3 Manejo de Recursos Didácticos <a class="header-anchor" href="#_3-3-manejo-de-recursos-didacticos" aria-label="Permalink to &quot;3.3 Manejo de Recursos Didácticos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recurso</th><th>Buenas Prácticas</th></tr></thead><tbody><tr><td><strong>Presentaciones (PowerPoint/Canva)</strong></td><td>Máximo 6-8 palabras por diapositiva. Usar imágenes grandes. NO leer las diapositivas textualmente.</td></tr><tr><td><strong>Pizarra</strong></td><td>Escribir con letra legible. Organizar el espacio (no escribir en cualquier parte). Borrar antes de reutilizar.</td></tr><tr><td><strong>Proyector/Computadora</strong></td><td>Tener todo preparado antes de empezar. Probar que los archivos abran correctamente. Tener un plan B si la tecnología falla.</td></tr><tr><td><strong>Material impreso</strong></td><td>Repartir al inicio si es referencia constante, o al final si es complementario.</td></tr></tbody></table><hr><h2 id="🏗️-capitulo-iv-los-9-eventos-de-gagne-aplicados-a-una-microclase" tabindex="-1">🏗️ CAPÍTULO IV: Los 9 Eventos de Gagné Aplicados a una Microclase <a class="header-anchor" href="#🏗️-capitulo-iv-los-9-eventos-de-gagne-aplicados-a-una-microclase" aria-label="Permalink to &quot;🏗️ CAPÍTULO IV: Los 9 Eventos de Gagné Aplicados a una Microclase&quot;">​</a></h2><p>Para conectar la teoría del manual anterior con la práctica de la microclase, veamos cómo cada evento de instrucción se ejecuta en una sesión real:</p>',37)),(o(),i(c,null,{default:a(()=>[s(r,{id:"mermaid-591",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20INICIO%20%5B%22%F0%9F%9F%A2%20FASE%20DE%20INICIO%22%5D%0A%20%20%20%20%20%20%20%20E1%5B%221.%20Ganar%20la%20atenci%C3%B3n%22%5D%0A%20%20%20%20%20%20%20%20E2%5B%222.%20Informar%20objetivos%22%5D%0A%20%20%20%20%20%20%20%20E3%5B%223.%20Estimular%20conocimientos%20previos%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20DESARROLLO%20%5B%22%F0%9F%94%B5%20FASE%20DE%20DESARROLLO%22%5D%0A%20%20%20%20%20%20%20%20E4%5B%224.%20Presentar%20contenido%22%5D%0A%20%20%20%20%20%20%20%20E5%5B%225.%20Proporcionar%20gu%C3%ADa%22%5D%0A%20%20%20%20%20%20%20%20E6%5B%226.%20Provocar%20desempe%C3%B1o%22%5D%0A%20%20%20%20%20%20%20%20E7%5B%227.%20Dar%20retroalimentaci%C3%B3n%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20CIERRE%20%5B%22%F0%9F%94%B4%20FASE%20DE%20CIERRE%22%5D%0A%20%20%20%20%20%20%20%20E8%5B%228.%20Evaluar%20desempe%C3%B1o%22%5D%0A%20%20%20%20%20%20%20%20E9%5B%229.%20Retenci%C3%B3n%20y%20transferencia%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20INICIO%20--%3E%20DESARROLLO%0A%20%20%20%20DESARROLLO%20--%3E%20CIERRE%0A%0A%20%20%20%20style%20INICIO%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20DESARROLLO%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20CIERRE%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<h4 id="ejemplo-completo-microclase-sobre-direcciones-ip" tabindex="-1">Ejemplo Completo: Microclase sobre &quot;Direcciones IP&quot; <a class="header-anchor" href="#ejemplo-completo-microclase-sobre-direcciones-ip" aria-label="Permalink to &quot;Ejemplo Completo: Microclase sobre &quot;Direcciones IP&quot;&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Fase</th><th>Evento</th><th>Lo que hace el expositor</th></tr></thead><tbody><tr><td><strong>Inicio</strong></td><td>1. Ganar atención</td><td>&quot;¿Alguna vez han intentado enviar una carta sin dirección? ¿Qué pasaría? Pues así funciona Internet sin las IP.&quot;</td></tr><tr><td></td><td>2. Informar objetivos</td><td>&quot;Hoy van a aprender qué es una dirección IP, cuántas clases existen y cómo identificarlas.&quot;</td></tr><tr><td></td><td>3. Conocimientos previos</td><td>&quot;¿Alguien sabe cómo averiguar la IP de su computadora? ¿Qué números ven cuando lo hacen?&quot;</td></tr><tr><td><strong>Desarrollo</strong></td><td>4. Presentar contenido</td><td>Explicar la estructura de IPv4 (4 octetos), las clases A, B, C con diapositivas claras.</td></tr><tr><td></td><td>5. Proporcionar guía</td><td>&quot;Piénsenlo así: la clase A es como un código de área telefónico que cubre un país entero, la clase C es como un número de extensión interno.&quot;</td></tr><tr><td></td><td>6. Provocar desempeño</td><td>&quot;Miren estas 5 direcciones IP. Clasifíquenlas en A, B o C. Tienen 2 minutos.&quot;</td></tr><tr><td></td><td>7. Retroalimentación</td><td>&quot;La IP 192.168.1.1 es clase C porque el primer octeto está entre 192 y 223. ¡Muy bien!&quot;</td></tr><tr><td><strong>Cierre</strong></td><td>8. Evaluar desempeño</td><td>&quot;Sin mirar sus notas: ¿cuál es el rango del primer octeto de una clase B?&quot;</td></tr><tr><td></td><td>9. Retención/transferencia</td><td>&quot;La próxima clase veremos subredes. Para prepararse, busquen cuál es la IP pública de su casa y tráiganla anotada.&quot;</td></tr></tbody></table><hr><h2 id="🧪-capitulo-v-actividades-de-consolidacion" tabindex="-1">🧪 CAPÍTULO V: Actividades de Consolidación <a class="header-anchor" href="#🧪-capitulo-v-actividades-de-consolidacion" aria-label="Permalink to &quot;🧪 CAPÍTULO V: Actividades de Consolidación&quot;">​</a></h2><h3 id="actividad-1-analisis-de-microclase" tabindex="-1">Actividad 1: Análisis de Microclase <a class="header-anchor" href="#actividad-1-analisis-de-microclase" aria-label="Permalink to &quot;Actividad 1: Análisis de Microclase&quot;">​</a></h3><p>Observa una presentación o clase grabada en video (puede ser de YouTube) y evalúa:</p><ul><li>¿El expositor aplicó los 9 eventos de Gagné? ¿Cuáles faltaron?</li><li>¿Cuál fue la técnica de inicio utilizada? ¿Fue efectiva?</li><li>¿Hubo participación activa del grupo durante el desarrollo?</li><li>¿El cierre sintetizó correctamente los puntos clave?</li></ul><h3 id="actividad-2-planificacion-de-tu-microclase" tabindex="-1">Actividad 2: Planificación de tu Microclase <a class="header-anchor" href="#actividad-2-planificacion-de-tu-microclase" aria-label="Permalink to &quot;Actividad 2: Planificación de tu Microclase&quot;">​</a></h3><p>Selecciona un tema de informática (puede ser cualquier contenido del PNFI) y diseña el plan escrito de tu microclase de 15 minutos. Tu plan debe incluir:</p><ol><li><strong>Tema y objetivo</strong> (usando la taxonomía de Bloom).</li><li><strong>Descripción del Inicio</strong> (qué técnica usarás para ganar la atención).</li><li><strong>Descripción del Desarrollo</strong> (contenido, recursos y actividad participativa).</li><li><strong>Descripción del Cierre</strong> (cómo sintetizarás y evaluarás).</li><li><strong>Recursos necesarios</strong> (diapositivas, pizarra, material impreso, etc.).</li></ol><h3 id="actividad-3-practica-de-oratoria" tabindex="-1">Actividad 3: Práctica de Oratoria <a class="header-anchor" href="#actividad-3-practica-de-oratoria" aria-label="Permalink to &quot;Actividad 3: Práctica de Oratoria&quot;">​</a></h3><p>Graba un video de 3 minutos donde expliques un concepto técnico de tu carrera. Luego, revísalo y evalúa tu comunicación verbal (volumen, ritmo, muletillas) y no verbal (contacto visual, postura, gesticulación). Anota 3 fortalezas y 3 áreas de mejora.</p><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Microclase (Micro-enseñanza):</strong> Técnica de formación docente que consiste en la ejecución planificada de una sesión instruccional de duración reducida ante un grupo pequeño, con fines de práctica, observación y retroalimentación de habilidades pedagógicas.</li><li><strong>Inicio Instruccional:</strong> Primera fase de una sesión de enseñanza cuyo propósito es captar la atención, activar conocimientos previos y comunicar los objetivos de aprendizaje al estudiante.</li><li><strong>Desarrollo Instruccional:</strong> Fase central donde se presenta el contenido nuevo, se proporcionan guías de aprendizaje y se provoca la participación activa del alumno para facilitar la codificación de la información.</li><li><strong>Cierre Instruccional:</strong> Fase final que sintetiza los puntos clave, evalúa informalmente la comprensión y promueve la retención y transferencia del aprendizaje a nuevos contextos.</li><li><strong>Oratoria:</strong> Arte y técnica de hablar en público de manera eficaz, clara y persuasiva, controlando elementos verbales (volumen, ritmo, dicción) y no verbales (postura, contacto visual, gesticulación).</li><li><strong>Recurso Didáctico:</strong> Todo material, herramienta o medio (físico o digital) utilizado por el docente para facilitar, apoyar y enriquecer el proceso de enseñanza-aprendizaje.</li><li><strong>Retroalimentación (Feedback):</strong> Información proporcionada al alumno sobre su desempeño que le permite identificar aciertos, corregir errores y orientar su aprendizaje futuro.</li><li><strong>Conflicto Cognitivo:</strong> Estado de desequilibrio mental que ocurre cuando el alumno encuentra información nueva que contradice o desafía sus esquemas previos, motivándolo a reorganizar su conocimiento.</li></ul>',15))])}const E=d(p,[["render",m]]);export{A as __pageData,E as default};
